const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{
const p=await b.newPage({viewport:{width:390,height:1000},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(require('./island-test-helper.cjs'));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');
for(const island of [0,1])for(let i=0;i<(island?6:8);i++){await p.evaluate(({island,i})=>{DEUTSCH_JOURNEY.select(island);DEUTSCH_JOURNEY.open(i)},{island,i});const portrait=p.locator('.market-encounter>.market-merchant').first();if(await portrait.evaluate(e=>getComputedStyle(e).animationName)!=='character-hello')throw Error('Missing character greeting '+island+':'+i);await p.click('#alContinue');if(await p.locator('.market-task-portrait').first().evaluate(e=>getComputedStyle(e).animationName)!=='none')throw Error('Character moves during answer');}
const complete=async(index,correct=true,train=false)=>{await p.evaluate(({index,train})=>{DEUTSCH_JOURNEY.select(0);if(train){DEUTSCH_JOURNEY.open(index);document.querySelector('#alContinue').click();finishTrainingToTest()}else DEUTSCH_JOURNEY.test(index)},{index,train});await p.evaluate(correct=>{const a=DEUTSCH_ADAPTIVE;while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];a.answer(correct?(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de):'wrong');document.querySelector('#alNext').click()}},correct)};
await complete(0,true,true);if(await p.locator('[data-clue-new="true"]').count()!==1||await p.locator('.clue-pocket li').count()!==8||await p.locator('.clue-pocket .is-collected').count()!==1)throw Error('New clue collection missing');if(await p.locator('[data-team-state="success"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='character-cheer')throw Error('Character does not celebrate');await p.locator('.team-clue-reward').scrollIntoViewIfNeeded();await p.waitForFunction(()=>document.querySelector('[data-clue-flight="started"]'));await p.waitForFunction(()=>document.querySelector('[data-clue-destination].clue-landed'));if(await p.locator('.clue-flight').count())throw Error('Flight decoration leaked');fs.mkdirSync('audit-screenshots',{recursive:true});await p.locator('.team-clue-reward').screenshot({path:'audit-screenshots/clue-collection-reward.png',animations:'disabled'});await p.click('#alDone');if(await p.locator('[data-clue-fragment="0"].is-new-fragment').count()!==1||await p.locator('[data-clue-count]').textContent()!=='1 / 8')throw Error('Map did not acknowledge clue');
await complete(0);if(await p.locator('[data-clue-new="true"]').count()||await p.locator('.clue-pocket .is-collected').count()!==1)throw Error('Replay awarded duplicate clue');await complete(0,false);if(await p.locator('.team-clue-reward').count())throw Error('Failed replay awards clue');if(await p.locator('[data-team-state="encourage"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='character-encourage')throw Error('Missing encouragement');await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));if(await p.locator('[data-clue-count]').textContent()!=='1 / 8')throw Error('Failed replay erased clue');
await p.emulateMedia({reducedMotion:'reduce'});await complete(1,true,true);await p.locator('.team-clue-reward').scrollIntoViewIfNeeded();if(await p.locator('[data-team-state="success"]>.market-merchant').evaluate(e=>getComputedStyle(e).animationName)!=='none'||await p.locator('.clue-flight').count())throw Error('Reduced motion animated reward');if(await p.locator('.clue-pocket .is-collected').count()!==2)throw Error('Reduced motion lost clue');
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Clue reward overflow '+width)}await p.reload();await p.click('#learningTab');await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));if(await p.locator('[data-clue-count]').textContent()!=='2 / 8')throw Error('Collection lost on reload');if(errors.length)throw Error(errors.join(';'));console.log('PASS character reactions and clue collection: both island casts, still task portraits, first reward flight, map acknowledgement, duplicate/failure retention, reduced motion, responsive layouts and reload');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
